BEGIN;

CREATE TABLE "AcquisitionRequestStatusTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "AcquisitionRequestStatusTypes" ("Id", "Key") VALUES
    (1, 'Open'), (2, 'Approved'), (3, 'Searching'), (4, 'Downloading'),
    (5, 'Importing'), (6, 'Completed'), (7, 'Rejected'), (8, 'Failed'), (9, 'Cancelled');

CREATE TABLE "AcquisitionRequests" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "WorkId" bigint NOT NULL REFERENCES "Works" ("Id") ON DELETE RESTRICT,
    -- A deleted profile's requests stay with its account and keep counting against its limit.
    "RequestedByProfileId" bigint NULL REFERENCES "Profiles" ("Id") ON DELETE SET NULL,
    -- The account's request rule bounds and approves the request.
    "RequestedByAccountId" bigint NOT NULL REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    "UiLocaleId" bigint NOT NULL REFERENCES "UiLocales" ("Id") ON DELETE RESTRICT,
    "GamePlatformId" bigint NULL REFERENCES "GamePlatforms" ("Id") ON DELETE RESTRICT,
    "AcquisitionRequestStatusTypeId" smallint NOT NULL DEFAULT 1 REFERENCES "AcquisitionRequestStatusTypes" ("Id"),
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    "DecidedByAccountId" bigint REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    "DecidedAt" timestamptz,
    CHECK (("DecidedByAccountId" IS NULL) = ("DecidedAt" IS NULL)),
    CHECK ("AcquisitionRequestStatusTypeId" NOT IN (2, 3, 4, 5, 6, 7, 8) OR "DecidedAt" IS NOT NULL)
);
CREATE UNIQUE INDEX "UX_AcquisitionRequests_ActiveIntent"
    ON "AcquisitionRequests" ("RequestedByProfileId", "WorkId", "UiLocaleId", "GamePlatformId") NULLS NOT DISTINCT
    WHERE "AcquisitionRequestStatusTypeId" IN (1, 2, 3, 4, 5) AND "RequestedByProfileId" IS NOT NULL;
CREATE INDEX "IX_AcquisitionRequests_Queue" ON "AcquisitionRequests" ("CreatedAt" DESC, "Id" DESC);
CREATE INDEX "IX_AcquisitionRequests_Profile" ON "AcquisitionRequests" ("RequestedByProfileId", "CreatedAt" DESC, "Id" DESC);
CREATE INDEX "IX_AcquisitionRequests_Account" ON "AcquisitionRequests" ("RequestedByAccountId", "CreatedAt");

-- Indexers, download clients and subtitle providers share one connection owner; the type's role decides where a connection is used.
CREATE TABLE "AcquisitionConnectionTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE,
    -- 1 searches releases, 2 downloads them, 3 provides subtitles.
    "AcquisitionConnectionRoleId" smallint NOT NULL CHECK ("AcquisitionConnectionRoleId" BETWEEN 1 AND 3)
);
-- Direct sources (Gutenberg, OPDS, Anna's Archive) search and download without a download client; Usenet servers feed Jularr's own downloader.
INSERT INTO "AcquisitionConnectionTypes" ("Id", "Key", "AcquisitionConnectionRoleId") VALUES
    (1, 'Newznab', 1), (2, 'Sabnzbd', 2), (3, 'Gutenberg', 1), (4, 'Opds', 1), (5, 'AnnasArchive', 1), (6, 'Usenet', 2), (7, 'OpenSubtitles', 3), (8, 'SubDl', 3);

CREATE TABLE "AcquisitionConnections" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(128) NOT NULL CHECK (length(btrim("Name")) > 0),
    "AcquisitionConnectionTypeId" smallint NOT NULL REFERENCES "AcquisitionConnectionTypes" ("Id"),
    "BaseUrl" varchar(500) NULL CHECK ("BaseUrl" ~ '^https?://'),
    -- A news server: its host, port (empty: 563 with SSL, 119 without) and SSL.
    "Host" varchar(253) NULL CHECK (length("Host") > 0),
    "Port" integer NULL CHECK ("Port" BETWEEN 1 AND 65535),
    "UseSsl" boolean NULL,
    "ProtectedApiKey" bytea NULL,
    "Username" varchar(128) NULL CHECK (length(btrim("Username")) > 0),
    -- OpenSubtitles needs an account password beside its API key.
    "ProtectedPassword" bytea NULL,
    "IsEnabled" boolean NOT NULL DEFAULT TRUE,
    "Priority" integer NOT NULL DEFAULT 25 CHECK ("Priority" BETWEEN 1 AND 100),
    "Categories" integer[] NOT NULL DEFAULT '{}',
    "DownloadCategory" varchar(64) NULL,
    "RemotePath" varchar(1024) NULL,
    "LocalPath" varchar(1024) NULL,
    "MaxConnections" smallint NULL CHECK ("MaxConnections" BETWEEN 1 AND 50),
    "Capabilities" jsonb NULL,
    "CheckedAt" timestamptz NULL,
    "LastErrorKey" varchar(64) NULL,
    -- Indexers: the media types they serve (empty: all), manual-only ones, daily query and grab limits with the day's counts, and the backoff after failed searches.
    "MediaTypeIds" integer[] NOT NULL DEFAULT '{}' CHECK ("MediaTypeIds" <@ ARRAY[1, 2, 3, 6, 7]),
    "SearchesAutomatically" boolean NOT NULL DEFAULT TRUE,
    "QueryLimit" integer NULL CHECK ("QueryLimit" > 0),
    "GrabLimit" integer NULL CHECK ("GrabLimit" > 0),
    "QueryCount" integer NOT NULL DEFAULT 0 CHECK ("QueryCount" >= 0),
    "GrabCount" integer NOT NULL DEFAULT 0 CHECK ("GrabCount" >= 0),
    "CountedOn" date NULL,
    "FailureCount" integer NOT NULL DEFAULT 0 CHECK ("FailureCount" >= 0),
    "RetryAt" timestamptz NULL,
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CHECK (("RemotePath" IS NULL) = ("LocalPath" IS NULL)),
    CHECK ("AcquisitionConnectionTypeId" = 1 OR "MediaTypeIds" = '{}' AND "SearchesAutomatically" AND "QueryLimit" IS NULL AND "GrabLimit" IS NULL),
    CHECK ("AcquisitionConnectionTypeId" = 2 OR ("DownloadCategory" IS NULL AND "RemotePath" IS NULL)),
    CHECK ("AcquisitionConnectionTypeId" IN (1, 3, 4, 5, 6) OR "ProtectedApiKey" IS NOT NULL),
    CHECK ("AcquisitionConnectionTypeId" IN (4, 6, 7) OR "Username" IS NULL),
    CHECK ("AcquisitionConnectionTypeId" = 7 OR "ProtectedPassword" IS NULL),
    CHECK (("AcquisitionConnectionTypeId" = 6) = ("BaseUrl" IS NULL)),
    CHECK (("AcquisitionConnectionTypeId" = 6) = ("Host" IS NOT NULL AND "UseSsl" IS NOT NULL)),
    CHECK ("AcquisitionConnectionTypeId" = 6 OR "Port" IS NULL),
    CHECK ("AcquisitionConnectionTypeId" = 6 OR "MaxConnections" IS NULL),
    CHECK ("AcquisitionConnectionTypeId" NOT IN (5, 7, 8) OR "BaseUrl" ~ '^https://')
);

-- Quality profiles; one default per media type and subtype, Works may choose another.
CREATE TABLE "AcquisitionProfiles" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(128) NOT NULL CHECK (length(btrim("Name")) > 0),
    "MediaTypeId" smallint NOT NULL REFERENCES "MediaTypes" ("Id"),
    "MediaSubtypeId" smallint NULL,
    "IsDefault" boolean NOT NULL DEFAULT FALSE,
    "Definition" jsonb NOT NULL,
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0),
    FOREIGN KEY ("MediaSubtypeId", "MediaTypeId") REFERENCES "MediaSubtypeParents" ("MediaSubtypeId", "MediaTypeId")
);
CREATE UNIQUE INDEX "UX_AcquisitionProfiles_Default" ON "AcquisitionProfiles" ("MediaTypeId", "MediaSubtypeId") NULLS NOT DISTINCT WHERE "IsDefault";
INSERT INTO "AcquisitionProfiles" ("Name", "MediaTypeId", "MediaSubtypeId", "IsDefault", "Definition") VALUES
    ('Movies 1080p', 1, NULL, TRUE, '{"AllowedQualities":["BLURAY-1080p","WEB-1080p","HDTV-1080p","BLURAY-720p","WEB-720p","HDTV-720p"],"QualityOrder":["BLURAY-1080p","WEB-1080p","HDTV-1080p","BLURAY-720p","WEB-720p","HDTV-720p"],"UpgradeAllowed":true,"UpgradeCutoffQuality":"WEB-1080p","MinimumSizeBytes":null,"MaximumSizeBytes":null,"MustContain":[],"MustNotContain":[],"RequiredRegex":[],"RejectedRegex":[],"ScoreRules":[{"Id":1,"Name":"Prefer Proper","Field":"Proper","Match":"Equals","Value":"true","Score":5},{"Id":2,"Name":"Prefer Repack","Field":"Repack","Match":"Equals","Value":"true","Score":5}]}'),
    ('Series 1080p', 2, NULL, TRUE, '{"AllowedQualities":["BLURAY-1080p","WEB-1080p","HDTV-1080p","BLURAY-720p","WEB-720p","HDTV-720p"],"QualityOrder":["BLURAY-1080p","WEB-1080p","HDTV-1080p","BLURAY-720p","WEB-720p","HDTV-720p"],"UpgradeAllowed":true,"UpgradeCutoffQuality":"WEB-1080p","MinimumSizeBytes":null,"MaximumSizeBytes":null,"MustContain":[],"MustNotContain":[],"RequiredRegex":[],"RejectedRegex":[],"ScoreRules":[{"Id":1,"Name":"Prefer Proper","Field":"Proper","Match":"Equals","Value":"true","Score":5},{"Id":2,"Name":"Prefer Repack","Field":"Repack","Match":"Equals","Value":"true","Score":5}]}'),
    ('Books', 3, NULL, TRUE, '{"AllowedQualities":["EPUB","AZW3","MOBI","PDF","EBOOK"],"QualityOrder":["EPUB","AZW3","MOBI","PDF","EBOOK"],"UpgradeAllowed":false,"UpgradeCutoffQuality":null,"MinimumSizeBytes":null,"MaximumSizeBytes":null,"MustContain":[],"MustNotContain":[],"RequiredRegex":[],"RejectedRegex":[],"ScoreRules":[{"Id":1,"Name":"Prefer Retail","Field":"RawTitle","Match":"Contains","Value":"retail","Score":5}]}'),
    ('Manga', 3, 2, TRUE, '{"AllowedQualities":["CBZ","CBR","EPUB","PDF","COMIC"],"QualityOrder":["CBZ","CBR","EPUB","PDF","COMIC"],"UpgradeAllowed":false,"UpgradeCutoffQuality":null,"MinimumSizeBytes":null,"MaximumSizeBytes":null,"MustContain":[],"MustNotContain":[],"RequiredRegex":[],"RejectedRegex":[],"ScoreRules":[{"Id":1,"Name":"Prefer Digital","Field":"RawTitle","Match":"Contains","Value":"digital","Score":5}]}'),
    ('Music', 6, NULL, TRUE, '{"AllowedQualities":["FLAC-24","FLAC","ALAC","MP3-320","MP3-V0","MP3","AAC","AUDIO"],"QualityOrder":["FLAC-24","FLAC","ALAC","MP3-320","MP3-V0","MP3","AAC","AUDIO"],"UpgradeAllowed":false,"UpgradeCutoffQuality":null,"MinimumSizeBytes":null,"MaximumSizeBytes":null,"MustContain":[],"MustNotContain":[],"RequiredRegex":[],"RejectedRegex":[],"ScoreRules":[]}'),
    ('Games', 7, NULL, TRUE, '{"AllowedQualities":["GOG","NSP","XCI","ISO","ROM","GAME"],"QualityOrder":["GOG","NSP","XCI","ISO","ROM","GAME"],"UpgradeAllowed":false,"UpgradeCutoffQuality":null,"MinimumSizeBytes":null,"MaximumSizeBytes":null,"MustContain":[],"MustNotContain":[],"RequiredRegex":[],"RejectedRegex":[],"ScoreRules":[]}'),
    ('Light Novels', 3, 3, TRUE, '{"AllowedQualities":["EPUB","AZW3","MOBI","PDF","EBOOK"],"QualityOrder":["EPUB","AZW3","MOBI","PDF","EBOOK"],"UpgradeAllowed":false,"UpgradeCutoffQuality":null,"MinimumSizeBytes":null,"MaximumSizeBytes":null,"MustContain":[],"MustNotContain":[],"RequiredRegex":[],"RejectedRegex":[],"ScoreRules":[{"Id":1,"Name":"Prefer Retail","Field":"RawTitle","Match":"Contains","Value":"retail","Score":5}]}');

-- The quality a requester chose among those their rule offers.
ALTER TABLE "AcquisitionRequests" ADD "AcquisitionProfileId" bigint NULL REFERENCES "AcquisitionProfiles" ("Id") ON DELETE SET NULL;

-- Request rules bound how often and what accounts request and whether requests need approval; one is the default.
CREATE TABLE "RequestRules" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(60) NOT NULL UNIQUE CHECK (length(btrim("Name")) > 0),
    "Description" varchar(500) NULL,
    -- Without a limit requests are unlimited.
    "RequestLimit" integer NULL CHECK ("RequestLimit" BETWEEN 1 AND 10000),
    "PeriodDays" integer NOT NULL CHECK ("PeriodDays" BETWEEN 1 AND 365),
    "IsAutomaticApproval" boolean NOT NULL,
    -- Category keys; new categories are allowed until blocked.
    "BlockedMediaKeys" varchar(32)[] NOT NULL DEFAULT '{}',
    -- Quality profiles requesters may choose; none keeps the defaults.
    "AcquisitionProfileIds" bigint[] NOT NULL DEFAULT '{}',
    "IsDefault" boolean NOT NULL DEFAULT FALSE,
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0)
);
CREATE UNIQUE INDEX "UX_RequestRules_Default" ON "RequestRules" ("IsDefault") WHERE "IsDefault";
INSERT INTO "RequestRules" ("Name", "RequestLimit", "PeriodDays", "IsAutomaticApproval", "IsDefault") VALUES ('Standard', 10, 30, FALSE, TRUE);

-- An account follows the default rule unless assigned another; each value it sets overrides its rule's.
CREATE TABLE "AccountRequestRules" (
    "AccountId" bigint PRIMARY KEY REFERENCES "Accounts" ("Id") ON DELETE CASCADE,
    "RequestRuleId" bigint NULL REFERENCES "RequestRules" ("Id") ON DELETE SET NULL,
    "HasLimitOverride" boolean NOT NULL DEFAULT FALSE,
    "RequestLimit" integer NULL CHECK ("RequestLimit" BETWEEN 1 AND 10000),
    "PeriodDays" integer NULL CHECK ("PeriodDays" BETWEEN 1 AND 365),
    "IsAutomaticApproval" boolean NULL,
    "BlockedMediaKeys" varchar(32)[] NULL,
    "AcquisitionProfileIds" bigint[] NULL,
    CHECK ("HasLimitOverride" OR "RequestLimit" IS NULL)
);

-- The one resolved rule every account requests under.
CREATE VIEW "EffectiveRequestRules" AS
SELECT
    account."Id" AS "AccountId",
    rule."Id" AS "RequestRuleId",
    rule."Name" AS "RequestRuleName",
    assignment."RequestRuleId" IS NULL AS "IsInherited",
    COALESCE(assignment."HasLimitOverride" OR num_nonnulls(assignment."PeriodDays", assignment."IsAutomaticApproval", assignment."BlockedMediaKeys", assignment."AcquisitionProfileIds") > 0, FALSE)
        AS "IsOverridden",
    CASE WHEN assignment."HasLimitOverride" THEN assignment."RequestLimit" ELSE rule."RequestLimit" END AS "RequestLimit",
    COALESCE(assignment."PeriodDays", rule."PeriodDays") AS "PeriodDays",
    COALESCE(assignment."IsAutomaticApproval", rule."IsAutomaticApproval") AS "IsAutomaticApproval",
    COALESCE(assignment."BlockedMediaKeys", rule."BlockedMediaKeys") AS "BlockedMediaKeys",
    COALESCE(assignment."AcquisitionProfileIds", rule."AcquisitionProfileIds") AS "AcquisitionProfileIds"
FROM
    "Accounts" AS account
    LEFT JOIN "AccountRequestRules" AS assignment ON assignment."AccountId" = account."Id"
    JOIN "RequestRules" AS rule ON rule."Id" = COALESCE(assignment."RequestRuleId", (SELECT standard."Id" FROM "RequestRules" AS standard WHERE standard."IsDefault"));

-- Whole-Work targets with their automatic search state; a game is wanted per platform.
CREATE TABLE "WantedItems" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "WorkId" bigint NOT NULL REFERENCES "Works" ("Id") ON DELETE RESTRICT,
    "GamePlatformId" bigint NULL REFERENCES "GamePlatforms" ("Id") ON DELETE RESTRICT,
    "AcquisitionProfileId" bigint NULL REFERENCES "AcquisitionProfiles" ("Id") ON DELETE SET NULL,
    -- Library the target imports into; without one the type's first writable library.
    "LibraryRootId" bigint NULL,
    "IsPaused" boolean NOT NULL DEFAULT FALSE,
    -- Episodes and volumes that appear later are monitored.
    "MonitorsNewUnits" boolean NOT NULL DEFAULT TRUE,
    "SearchCount" integer NOT NULL DEFAULT 0 CHECK ("SearchCount" >= 0),
    "LastSearchedAt" timestamptz NULL,
    "NextSearchAt" timestamptz NULL,
    "LastOutcomeKey" varchar(64) NULL,
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "UX_WantedItems_Target" ON "WantedItems" ("WorkId", "GamePlatformId") NULLS NOT DISTINCT;
CREATE INDEX "IX_WantedItems_Due" ON "WantedItems" ("NextSearchAt", "Id") WHERE NOT "IsPaused";

-- Releases taken, failed or blocked for a target: tried releases, blocklist and history in one place.
CREATE TABLE "AcquisitionReleaseStatusTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "AcquisitionReleaseStatusTypes" ("Id", "Key") VALUES (1, 'Grabbed'), (2, 'Imported'), (3, 'Failed'), (4, 'Blocked'), (5, 'Allowed');

CREATE TABLE "AcquisitionReleases" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "WantedItemId" bigint NOT NULL REFERENCES "WantedItems" ("Id") ON DELETE CASCADE,
    "AcquisitionConnectionId" bigint NULL REFERENCES "AcquisitionConnections" ("Id") ON DELETE SET NULL,
    "ReleaseIdentity" varchar(600) NOT NULL,
    "Title" varchar(1000) NOT NULL,
    "SourceUrl" varchar(2048) NULL CHECK ("SourceUrl" ~ '^https?://'),
    "QualityKey" varchar(64) NULL,
    "ParentUnitNumber" smallint NULL CHECK ("ParentUnitNumber" >= 0),
    "UnitStart" smallint NULL CHECK ("UnitStart" >= 0),
    "UnitEnd" smallint NULL CHECK ("UnitEnd" >= "UnitStart"),
    "AcquisitionReleaseStatusTypeId" smallint NOT NULL REFERENCES "AcquisitionReleaseStatusTypes" ("Id"),
    "ReasonKey" varchar(64) NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CHECK (("UnitStart" IS NULL) = ("UnitEnd" IS NULL)),
    UNIQUE ("WantedItemId", "ReleaseIdentity")
);
CREATE INDEX "IX_AcquisitionReleases_Recent" ON "AcquisitionReleases" ("WantedItemId", "CreatedAt" DESC, "Id" DESC);
CREATE TABLE "RequestTargets" (
    "AcquisitionRequestId" bigint NOT NULL REFERENCES "AcquisitionRequests" ("Id") ON DELETE RESTRICT,
    "WantedItemId" bigint NOT NULL REFERENCES "WantedItems" ("Id") ON DELETE RESTRICT,
    PRIMARY KEY ("AcquisitionRequestId", "WantedItemId")
);
CREATE INDEX "IX_RequestTargets_Wanted" ON "RequestTargets" ("WantedItemId", "AcquisitionRequestId");

-- A profile's inbox: its requests and what arrived; managers also hear about failures.
-- An unread notice about the same subject counts up instead of repeating.
-- Staff types reach Owners and MediaManagers, Owner types only Owners.
CREATE TABLE "NotificationTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE,
    "IsStaffOnly" boolean NOT NULL DEFAULT FALSE,
    "IsOwnerOnly" boolean NOT NULL DEFAULT FALSE,
    CHECK (NOT "IsOwnerOnly" OR "IsStaffOnly")
);
INSERT INTO "NotificationTypes" ("Id", "Key", "IsStaffOnly", "IsOwnerOnly") VALUES
    (1, 'RequestApproved', FALSE, FALSE), (2, 'RequestRejected', FALSE, FALSE), (3, 'MediaAvailable', FALSE, FALSE), (4, 'DownloadFailed', TRUE, FALSE), (5, 'StorageOffline', TRUE, TRUE);

CREATE TABLE "Notifications" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "NotificationTypeId" smallint NOT NULL REFERENCES "NotificationTypes" ("Id"),
    "WorkId" bigint NULL REFERENCES "Works" ("Id") ON DELETE CASCADE,
    "Subject" varchar(500) NOT NULL CHECK (length(btrim("Subject")) > 0),
    "Link" varchar(512) NULL CHECK ("Link" ~ '^/[^/]'),
    "Occurrences" integer NOT NULL DEFAULT 1 CHECK ("Occurrences" > 0),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "ReadAt" timestamptz NULL
);
CREATE UNIQUE INDEX "UX_Notifications_Unread" ON "Notifications" ("ProfileId", "NotificationTypeId", (coalesce("WorkId", 0)), "Subject") WHERE "ReadAt" IS NULL;
CREATE INDEX "IX_Notifications_Profile" ON "Notifications" ("ProfileId", "CreatedAt" DESC, "Id" DESC);

CREATE TABLE "MutedNotificationTypes" (
    "ProfileId" bigint NOT NULL REFERENCES "Profiles" ("Id") ON DELETE CASCADE,
    "NotificationTypeId" smallint NOT NULL REFERENCES "NotificationTypes" ("Id"),
    PRIMARY KEY ("ProfileId", "NotificationTypeId")
);

COMMIT;
